    sovereign_bookmarktassel_palace = { name = "Suverena bookmarktassel palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
